<?php
require __DIR__ . '/includes/auth.php';
$adminTitle='Gallery';$errors=[];$edit=null;
if(isset($_GET['edit'])){$stmt=db()->prepare('SELECT * FROM gallery WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}
if(is_post()){
 verify_csrf();$action=$_POST['action']??'save';
 if($action==='delete'){$id=(int)$_POST['id'];$stmt=db()->prepare('SELECT image_path FROM gallery WHERE id=?');$stmt->execute([$id]);$row=$stmt->fetch();if($row)delete_uploaded_file($row['image_path']);db()->prepare('DELETE FROM gallery WHERE id=?')->execute([$id]);flash('success','Gallery item deleted.');redirect('admin/gallery.php');}
 $id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$category=trim($_POST['category']??'');$sort=(int)($_POST['sort_order']??0);$active=isset($_POST['is_active'])?1:0;$oldImage=$_POST['old_image']??null;$imageUrl=trim($_POST['image_url']??'');
 if($title==='')$errors[]='Title is required.';if($category==='')$errors[]='Category is required.';
 try{$image=upload_image($_FILES['image']??[],'gallery',$oldImage);}catch(Throwable $e){$errors[]=$e->getMessage();$image=$oldImage;}
 if($imageUrl!==''){$image=$imageUrl;}if(!$image)$errors[]='Please upload an image or provide an image URL.';
 if(!$errors){if($id){$stmt=db()->prepare('UPDATE gallery SET title=?,category=?,image_path=?,sort_order=?,is_active=? WHERE id=?');$stmt->execute([$title,$category,$image,$sort,$active,$id]);}else{$stmt=db()->prepare('INSERT INTO gallery(title,category,image_path,sort_order,is_active) VALUES(?,?,?,?,?)');$stmt->execute([$title,$category,$image,$sort,$active]);}flash('success','Gallery item saved.');redirect('admin/gallery.php');}
 $edit=['id'=>$id,'title'=>$title,'category'=>$category,'image_path'=>$image,'sort_order'=>$sort,'is_active'=>$active];
}
$items=db()->query('SELECT * FROM gallery ORDER BY sort_order,id DESC')->fetchAll();
require __DIR__ . '/includes/header.php';
