<div class="grid gap-7 xl:grid-cols-[420px_1fr]"><section class="admin-card p-6"><h2 class="font-display text-2xl font-bold uppercase text-brand-950"><?= $edit?'Edit Gallery Item':'Add Gallery Image' ?></h2><?php if($errors): ?><div class="mt-4 rounded-xl bg-red-50 p-4 text-sm font-bold text-red-700"><?= e(implode(' ',$errors)) ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="mt-6 grid gap-4"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><input type="hidden" name="old_image" value="<?= e($edit['image_path']??'') ?>"><label class="grid gap-2 text-sm font-bold">Title<input class="form-input" name="title" value="<?= e($edit['title']??'') ?>" required></label><label class="grid gap-2 text-sm font-bold">Category<input class="form-input" name="category" value="<?= e($edit['category']??'Residential') ?>" list="gallery-categories" required><datalist id="gallery-categories"><option>Residential</option><option>Commercial</option><option>Interiors</option><option>Work in Progress</option><option>Renovations</option></datalist></label><label class="grid gap-2 text-sm font-bold">Upload Image<input type="file" class="form-input" name="image" accept="image/jpeg,image/png,image/webp"></label><label class="grid gap-2 text-sm font-bold">Or Image URL<input class="form-input" type="url" name="image_url" placeholder="https://..."></label><?php if(!empty($edit['image_path'])): ?><img src="<?= upload_url($edit['image_path']) ?>" class="h-40 w-full rounded-xl object-cover"><?php endif; ?><label class="grid gap-2 text-sm font-bold">Sort Order<input type="number" class="form-input" name="sort_order" value="<?= e($edit['sort_order']??0) ?>"></label><label class="flex items-center gap-3 text-sm font-bold"><input type="checkbox" name="is_active" class="h-5 w-5" <?= ($edit['is_active']??1)?'checked':'' ?>>Visible on website</label><div class="flex gap-3"><button class="rounded-xl bg-brand-700 px-5 py-3 font-extrabold text-white">Save Item</button><?php if($edit): ?><a href="<?= url('admin/gallery.php') ?>" class="rounded-xl bg-slate-100 px-5 py-3 font-extrabold">Cancel</a><?php endif; ?></div></form></section><section class="admin-card p-6"><div class="flex items-center justify-between"><h2 class="font-display text-2xl font-bold uppercase text-brand-950">Gallery Images</h2><span class="text-sm font-bold text-slate-400"><?= count($items) ?> items</span></div><div class="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><?php foreach($items as $item): ?><article class="overflow-hidden rounded-2xl border border-slate-200"><img src="<?= upload_url($item['image_path']) ?>" class="aspect-[4/3] w-full object-cover"><div class="p-4"><div class="font-extrabold text-brand-950"><?= e($item['title']) ?></div><div class="mt-1 text-xs text-slate-500"><?= e($item['category']) ?></div><div class="mt-4 flex gap-2"><a href="?edit=<?= (int)$item['id'] ?>" class="rounded-lg bg-blue-50 p-2 text-blue-700"><i data-lucide="pencil" class="h-4 w-4"></i></a><form method="post" data-confirm="Delete this gallery image?"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="rounded-lg bg-red-50 p-2 text-red-700"><i data-lucide="trash-2" class="h-4 w-4"></i></button></form></div></div></article><?php endforeach; ?></div></section></div>
